import { mkdir, mkdtemp, writeFile } from "node:fs/promises";
import { tmpdir } from "node:os";
import { dirname, join } from "node:path";
import { describe, expect, it } from "vitest";
import { scanRepo } from "../src/scan/index.js";

// Microsoft.Extensions.AI ChatOptions sent through the Anthropic SDK's IChatClient adapter (src/data/sdk-vocab/
// nuget-Anthropic-meai.json, generated by tools/vocab/gen_meai.py from the published DLLs)
const repo = async (files: Record<string, string>) => {
  const d = await mkdtemp(join(tmpdir(), "vitasta-meai-"));
  for (const [p, t] of Object.entries(files)) {
    await mkdir(dirname(join(d, p)), { recursive: true });
    await writeFile(join(d, p), t);
  }
  return d;
};
const temps = async (files: Record<string, string>) =>
  ((await scanRepo(await repo(files))).usages as any[]).filter((u) => u.provider === "anthropic" && u.params?.includes("temperature"));

const runtime = `using Microsoft.Extensions.AI;
namespace App;
public sealed class Runtime {
    private readonly float? _temperature;
    public Runtime(Config config) { _temperature = config.Temperature; }
    public ChatOptions Options() {
        return new ChatOptions { ModelId = "m", Temperature = _temperature };
    }
}
`;
const config = `namespace App;
public sealed class Config {
    public float Temperature { get; set; } = 0.7f;
}
`;
const factory = (adapter: string) => `using Anthropic;
using Microsoft.Extensions.AI;
namespace App;
public static class Clients {
    public static IChatClient Make() => new AnthropicClient()${adapter};
}
`;

describe("MEAI ChatOptions through the Anthropic adapter", () => {
  it("reported as possible, with the config default it comes from", async () => {
    const us = await temps({ "src/Runtime.cs": runtime, "src/Config.cs": config, "src/Clients.cs": factory('.AsIChatClient("claude-sonnet-4-5")') });
    const opt = us.find((u) => u.file === "src/Runtime.cs" && u.line === 7);
    expect(opt?.confidence).toBe("possible");
    expect(opt?.reason).toMatch(/AsIChatClient/);
    expect(us.some((u) => u.file === "src/Config.cs" && u.line === 3)).toBe(true);
  });
  it("not without the adapter: ChatOptions alone could be any provider's", async () => {
    const us = await temps({ "src/Runtime.cs": runtime, "src/Config.cs": config, "src/Clients.cs": factory("") });
    expect(us.filter((u) => u.file === "src/Runtime.cs")).toEqual([]);
  });
});
